import java.util.*;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        int leftRemove = 0, rightRemove = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                leftRemove++;
            } else if (c == ')') {
                if (leftRemove > 0) leftRemove--;
                else rightRemove++;
            }
        }

        Set<String> result = new HashSet<>();
        dfs(s, 0, leftRemove, rightRemove, 0, new StringBuilder(), result);
        return new ArrayList<>(result);
    }

    private void dfs(String s, int index, int leftRemove, int rightRemove, int balance,
                     StringBuilder path, Set<String> result) {
        if (index == s.length()) {
            if (leftRemove == 0 && rightRemove == 0 && balance == 0) {
                result.add(path.toString());
            }
            return;
        }

        char c = s.charAt(index);
        int len = path.length();

        if (c == '(') {
            if (leftRemove > 0) {
                dfs(s, index + 1, leftRemove - 1, rightRemove, balance, path, result);
            }
            path.append(c);
            dfs(s, index + 1, leftRemove, rightRemove, balance + 1, path, result);
            path.setLength(len);
        } else if (c == ')') {
            if (rightRemove > 0) {
                dfs(s, index + 1, leftRemove, rightRemove - 1, balance, path, result);
            }
            if (balance > 0) {
                path.append(c);
                dfs(s, index + 1, leftRemove, rightRemove, balance - 1, path, result);
                path.setLength(len);
            }
        } else {
            path.append(c);
            dfs(s, index + 1, leftRemove, rightRemove, balance, path, result);
            path.setLength(len);
        }
    }
}

